+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("[^@\\s]+@[^@\\s]+\\.[^@\\s]+");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessages messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final Dialog discardDialog = new Dialog();
+    private ContinueNavigationAction postponedNavigation;
+
+    /** Set while the form is cleared after a send, so that clearing does not re-enable Send. */
+    private boolean clearing;
+
+    public ContactView(ContactMessages messages) {
+        this.messages = messages;
+
+        setSizeFull();
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> onEdit());
+        email.addValueChangeListener(e -> onEdit());
+        phone.addValueChangeListener(e -> onEdit());
+        message.addValueChangeListener(e -> onEdit());
+
+        message.setWidthFull();
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setColspan(message, 2);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(e -> send());
+        // Enter sends; Shift+Enter still inserts a line break in the message.
+        Shortcuts.addShortcutListener(form, e -> send(), Key.ENTER)
+                .setBrowserDefaultAllowed(false);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setAllRowsVisible(true);
+        grid.setItems(messages.all());
+
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.add(new Paragraph("The contact form has text that has not been sent."));
+        discardDialog.getFooter().add(
+                new Button("Keep editing", e -> keepEditing()),
+                new Button("Discard", e -> discard()));
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid, discardDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            postponedNavigation = event.postpone();
+            discardDialog.open();
+        }
+    }
+
+    private void onEdit() {
+        if (!clearing) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void send() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        clearValidation();
+        if (!validate()) {
+            return;
+        }
+        messages.add(new ContactMessage(text(name), text(email), text(phone), text(message)));
+        Notification.show("Message sent");
+
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+        send.setEnabled(false);
+        grid.setItems(messages.all());
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+        String emailText = text(email);
+        String phoneText = text(phone);
+        String messageText = text(message);
+
+        if (text(name).isEmpty()) {
+            invalid(name, "Name is required");
+            valid = false;
+        }
+        if (!emailText.isEmpty() && !EMAIL.matcher(emailText).matches()) {
+            invalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailText.isEmpty() && phoneText.isEmpty()) {
+            invalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageText.isEmpty()) {
+            invalid(message, "Message is required");
+            valid = false;
+        } else if (messageText.length() > MAX_MESSAGE_LENGTH) {
+            invalid(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private boolean hasInput() {
+        return !text(name).isEmpty() || !text(email).isEmpty()
+                || !text(phone).isEmpty() || !text(message).isEmpty();
+    }
+
+    private void keepEditing() {
+        postponedNavigation = null;
+        discardDialog.close();
+    }
+
+    private void discard() {
+        discardDialog.close();
+        ContinueNavigationAction navigation = postponedNavigation;
+        postponedNavigation = null;
+        if (navigation != null) {
+            navigation.proceed();
+        }
+    }
+
+    private static void invalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static String text(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value.trim();
+    }
+}
